    public void commitChanges() throws PersistenceException {
        if (closed) {
            throw new PersistenceException("Database is closed, cannot commit.");
        }
        try {
            MetaObject meta = MetaObjectFactory.getMeta(metaObject);
            List<Object> objects = tables.get(meta);
            for (Object object : objects) {
                commitObject(object);
            }
        } catch (PersistenceException e) {
            log.error("Error committing changes: ", e);
        }
    }

    private void commitObject(Object object) throws PersistenceException {
        try {
            DatabaseManager.getInstance().save(object);
        } catch (PersistenceException e) {
            log.error("Error saving object: ", e);
